def make_badge(width, label, icon_svg, dark=True):
    container_bg = "#241e24" if dark else "#f5eef5"
    chip_color = "#664869" if dark else "#e8d0e7"
    text_color = "#fed7ff" if dark else "#3e1e42"
    border_attr = ' stroke="#3e2e3e" stroke-width="1"' if dark else ' stroke="#d8c4d8" stroke-width="1"'
    
    chip = COOKIE_CHIP.format(chip_color=chip_color)
    icon = icon_svg.format(icon_color=text_color)
    
    font_family = "system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif"
    return f"""<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="38" viewBox="0 0 {width} 38">
  <defs>
    <style>
      .label {{ font-family: {font_family}; font-size: 13.5px; font-weight: 600; letter-spacing: 0.2px; }}
    </style>
  </defs>
  <path d="M19,0H{width-19}A19,19 0 0 1 {width},19V19A19,19 0 0 1 {width-19},38H19A19,19 0 0 1 0,19V19A19,19 0 0 1 19,0Z" fill="{container_bg}"{border_attr}/>
  {chip}
  {icon}
  <text x="44" y="24" fill="{text_color}" class="label">{label}</text>
</svg>"""

badges = [
    ("badge-gecko.svg", 168, "GeckoView 159", ICON_GECKO),
    ("badge-rustadblock.svg", 158, "Rust Adblock", ICON_SHIELD),
    ("badge-privacy.svg", 146, "No Telemetry", ICON_PRIVACY),
    ("badge-extensions.svg", 150, "Add-ons Ready", ICON_EXTENSIONS),
]

for filename, width, label, icon in badges:
    dark_svg = make_badge(width, label, icon, dark=True)
    light_svg = make_badge(width, label, icon, dark=False)
    with open(os.path.join(DARK_DIR, filename), "w") as f:
        f.write(dark_svg)
    with open(os.path.join(LIGHT_DIR, filename), "w") as f:
        f.write(light_svg)

print("Generated custom Petal M3E badges.")
